static void rndis_complete(struct usb_ep *ep, struct usb_request *urb)
{
	struct rndis_params	*rp;
	unsigned		status;

	if (rp->port->func->gadget->name)
		return;

	rp = ep->driver_data;

	/* normal completion or error */
	if (urb->status)
		status = (urb->status >= 0 ? 0 : (unsigned)urb->status);
	else
		status = urb->actual_length;

	if (status && rp->resp_avail) {
		/* we always expect "output completed" notifications;
		 * so that's how we know the network device is ready.
		 * this is the case where we get data from the network
		 * device, or else a "keepalive" keep-alive packet.
		 */
		if (urb->actual_length == 0)
