	 * NOTE that if this is used for input, rndis_complete must
	 * update rp->data_len and then call rp_avail() eventually.
	 */
	if (status && usb_ep_queue(ep, urb, GFP_KERNEL)) {
		DBG(DBG_TX, "Requeue error %d\n", status);
		usb_ep_set_halt(ep);
	}
}

