int read_time(int fd) {

	struct timeval time;
	fd_set mask;

	FD_ZERO(&mask);
	FD_SET(fd, &mask);

	select(fd+1, &mask, 0, 0, 0);
	if (FD_ISSET(fd, &mask)) {
		/* Data is available */
