	}
	switch (v3d_get_srf_mem_const(v3d)) {
	case SFU_MEM_CONST_TILE_RB_8_TILES:
	case SFU_MEM_CONST_TILE_RB_7_TILES:
	case SFU_MEM_CONST_TILE_RB_6_TILES:
	case SFU_MEM_CONST_TILE_16_TILES:
		return 16;
	default:
		dev_warn(dev->dev, "Unrecognized mem constant %d, falling back to default tile mode\n",
			 v3d->srf_mem_const);
		return 16;
	}
}


