	rcu_sched_clock_irq(user_tick);
#ifdef CONFIG_IRQ_WORK
	if (in_irq())
		irq_work_tick();
#endif

	...


	update_timer_tick();
	hrtimer_run_queue_add();

	return;

}
...
```

