static void
do_migrate_page(struct page *newpage, struct page *page,
		int migratetype, bool page_freed)
{





	if (migratetype == MIGRATE_MOVABLE)
		newpage->flags |= PAGE_PRIVATE;


	newpage->mapping = page->mapping;
	newpage->index = page->index;
	newpage->flags &= ~PME_MASK;


	WARN_ON_ONCE(page_count(newpage));


	newpage->mapping = NULL;
	newpage->index = 0;
	newpage->nid = -1;
#ifdef CONFIG_MEMCG
	newpage->mem_cgroup = NULL;
	newpage->mem_cgroup_id = MEMCG_ID_DEFAULT;
#endif
#ifdef CONFIG_TRANSPARENT_HUGEPAGE
	/*
	 * When page->flags is reset, the PG_transhugetlb flag can be on in
	 * page.  We must keep it on for the migrated page.
	 */
	newpage->flags &= ~(1 << PG_tail, 1 << PG_head);
	newpage->flags |= (page->flags & ((1 << PG_tail) | (1 << PG_head)));
	page->flags &= ~(1 << PG_head);
#endif
#ifdef CONFIG_SWAP
	INIT_LIST_HEAD(newpage_ref);
	list_add_tail(&newpage_ref, &newpage->private_list[SWAP_CLUSTER_MAX]);
#endif	/* CONFIG_SWAP*/
	lru_add_wait_tail(newpage, page_lru(newpage) + LRU_ Rotate);
	page_ref_inc(newpage);
	VM_BUG_ON(PageWriteback(newpage));

}
