static void tipc_link_input(struct sock *sk, int len, void *data,
			    void *rx_addr)
{
	struct tipc_sk *tsk = tipc_sk(sk);
	struct nlmsghdr *nlp;
	u32 rxid;

	read_lock_bh(&tsk->rcvq_lock);
	if (skb_queue_empty(&tsk->sk_receive_queue))
		goto exit;

	rxid =  nlattr_find_nested(skb_peek(&tsk->sk_receive_queue), TIPC_NLA_RXID);
	skb_queue_walk(&tsk->sk_receive_queue, skb) {
		nlp = nlmsg_hdr(skb);
		if (likely((nlp->nlmsg_seq == rxid)))
			tsk->rcv_nxt = 	
#if LINUX_VERSION_CODE >= KERNEL_VERSION(3,10,0)
							nlmsg_parse_v3
#else
							__nlmsg_parse
#endif
							(tsk->rx_skb,
							 &skb->cb->args[1],
							 tsk->gen_valid);
		skb_queue_splice(tsk->sk_receive_queue.prev, &sk->sk_receive_queue,
				 tsk->sk_receive_queue.next);
		rcu_read_unlock();
		sock_set_flag(sk, SOCK_QUEUE_RCVD_LT);
		break;
	}
exit:
	read_unlock_bh(&tsk->rcvq_lock);
}

